function bearing(lat1,lon1,lat2,lon2){const r=Math.PI/180,a1=lat1*r,a2=lat2*r,dl=(lon2-lon1)*r;const y=Math.sin(dl)*Math.cos(a2),x=Math.cos(a1)*Math.sin(a2)-Math.sin(a1)*Math.cos(a2)*Math.cos(dl);return(Math.atan2(y,x)/r+360)%360}
function direction(deg){const dirs=['Utara','Timur Laut','Timur','Tenggara','Selatan','Barat Daya','Barat','Barat Laut'];return dirs[Math.round(deg/45)%8]}
function renderQibla(){const el=$('#qiblaDegrees');if(!el)return;if(!state.location){el.textContent='—°';$('#qiblaDirection').textContent='Tetapkan lokasi untuk mengira arah';$('#qiblaVisual .qibla-arrow').style.transform='rotate(0deg)';$('#headingReadout').textContent='Kompas belum diaktifkan';return}const deg=bearing(Number(state.location.lat),Number(state.location.lon),KAABA.lat,KAABA.lon);el.textContent=`${deg.toFixed(1)}°`;$('#qiblaDirection').textContent=direction(deg);$('#qiblaVisual .qibla-arrow').style.transform=`rotate(${deg}deg)`;$('#qiblaMessage').textContent=`Lokasi: ${state.location.label}. Bearing dikira secara geografi.`}
function hijriParts(d){try{const parts=new Intl.DateTimeFormat('en-US-u-ca-islamic-umalqura',{year:'numeric',month:'numeric',day:'numeric'}).formatToParts(d);return{year:Number(parts.find(x=>x.type==='year')?.value),month:Number(parts.find(x=>x.type==='month')?.value),day:Number(parts.find(x=>x.type==='day')?.value)}}catch(_){return{year:0,month:0,day:0}}}
function renderCalendarDates(d){const normal=d.toLocaleDateString('ms-MY',{weekday:'long',day:'numeric',month:'long',year:'numeric'});let h='Tarikh Islam tidak tersedia';try{h=new Intl.DateTimeFormat('ms-MY-u-ca-islamic-umalqura',{day:'numeric',month:'long',year:'numeric'}).format(d)}catch(_){}$('#dateText').textContent=normal;$('#hijriDateText').textContent=`Tarikh Islam · ${h}`}
function findNextRamadan(){const now=new Date();for(let i=0;i<500;i++){const d=new Date(now);d.setDate(now.getDate()+i);const h=hijriParts(d);if(h.month===9)return{date:d,parts:h}}return null}
function renderRamadan(){const now=new Date(),h=hijriParts(now),next=findNextRamadan();if(h.month===9){$('#ramadanStatus').textContent=`Ramadan ${h.year} sedang berlangsung`;$('#ramadanDayBadge').textContent=`Hari ${h.day}`;$('#ramadanCountdown').textContent='Teruskan rutin Ramadan hari ini.'}else if(next){const days=Math.ceil((next.date.setHours(0,0,0,0)-new Date(now.getFullYear(),now.getMonth(),now.getDate()).getTime())/86400000);$('#ramadanStatus').textContent=`Menuju Ramadan ${next.parts.year}`;$('#ramadanDayBadge').textContent=`${days} hari`;$('#ramadanCountdown').textContent=`Anggaran berdasarkan kalendar Umm al-Qura pada peranti.`}$('#ramadanImsak').textContent=state.location?.timings?.Imsak||'—';$('#ramadanIftar').textContent=state.location?.timings?.Maghrib||'—';const items=[['prayer','Jaga solat lima waktu'],['quran','Baca Al-Quran'],['dhikr','Zikir / doa harian'],['charity','Sedekah atau bantu orang lain'],['learning','Belajar ilmu Islam']];const day=localDateKey();const current=state.ramadan.checklist[day]||{};$('#ramadanChecklist').innerHTML=items.map(([id,label])=>`<label class="check-row"><input type="checkbox" data-ramadan="${id}" ${current[id]?'checked':''}><span>${label}</span></label>`).join('');const done=items.filter(x=>current[x[0]]).length;$('#ramadanDone').textContent=`${done}/${items.length}`;$('#ramadanProgress').style.width=`${done/items.length*100}%`;$('#ramadanNote').value=state.ramadan.note||''}
