function setupQuranPlan(){const sel=$('#quranPlanTarget'),btn=$('#quranPlanTodayBtn');if(!sel||!btn)return;sel.value=String(state.quranPlan.target||2);sel.onchange=()=>{state.quranPlan.target=Number(sel.value);saveState();renderQuranPlan()};btn.onclick=()=>{state.quranPlan.days[localDateKey()]=true;state.quranPlan.totalDays=Object.values(state.quranPlan.days).filter(Boolean).length;saveState();renderQuranPlan();toast('Rutin bacaan hari ini ditanda selesai.','#quranPlanText')};renderQuranPlan()}
