function exportData(){try{const payload={app:'NUR Academy',version:C.version,exportedAt:new Date().toISOString(),state};const blob=new Blob([JSON.stringify(payload,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`nur-academy-backup-${localDateKey()}.json`;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Backup berjaya dieksport.','#backupMessage')}catch(e){toast('Backup tidak dapat dieksport.','#backupMessage')}}
