function runGlobalSearch(q){const term=q.trim().toLowerCase(),results=[];if(!term){$('#globalResults').innerHTML='<div class="empty-state">Taip sesuatu untuk mula mencari.</div>';return}const feature=[['Waktu Solat','Semak lima waktu solat dan countdown.','solat'],['Al-Quran','Cari 114 surah, baca dan dengar audio.','quran'],['Zikir','Kiraan zikir tersimpan pada peranti.','zikir'],['Akademi','Pelajaran asas Islam.','akademi'],['Arah Kiblat','Kira bearing ke Kaabah berdasarkan lokasi.','kiblat'],['Tetapan','Urus tema, nama dan data.','tetapan'],['Ramadan','Rutin Ramadan dan jadual sahur/iftar.','ramadan']];feature.forEach(x=>{if(`${x[0]} ${x[1]}`.toLowerCase().includes(term))results.push({title:x[0],desc:x[1],go:x[2]})});LESSONS.forEach(x=>{if(`${x.title} ${x.intro}`.toLowerCase().includes(term))results.push({title:x.title,desc:x.intro,go:'akademi'})});if(surahs.length)surahs.filter(s=>`${s.number} ${s.englishName} ${s.name} ${s.englishNameTranslation}`.toLowerCase().includes(term)).slice(0,20).forEach(s=>results.push({title:s.englishName,desc:`Surah ${s.number} · ${s.numberOfAyahs} ayat`,surah:s.number}));if(!results.length){$('#globalResults').innerHTML='<div class="empty-state">Tiada hasil ditemui.</div>';return}$('#globalResults').innerHTML=results.slice(0,30).map((r,i)=>`<button class="search-result" data-result="${i}"><strong>${escapeHtml(r.title)}</strong><small>${escapeHtml(r.desc)}</small></button>`).join('');$('#globalResults').onclick=e=>{const b=e.target.closest('[data-result]');if(!b)return;const r=results[Number(b.dataset.result)];if(r.surah)openSurah(r.surah);else showPage(r.go)}}
