function ensureDaily(){const k=localDateKey();if(state.daily.lastDay===k)return;const prev=new Date();prev.setDate(prev.getDate()-1);const old=state.daily.lastDay;state.daily.streak=old===localDateKey(prev)?Number(state.daily.streak||0)+1:1;if(old&&state.daily.prayers&&Object.keys(state.daily.prayers).length)state.daily.history[old]=Object.assign({},state.daily.prayers);state.daily.lastDay=k;state.daily.prayers=state.daily.history[k]?Object.assign({},state.daily.history[k]):{};saveState()}
